import ast,base64,json,torch,hashlib
source=base64.b64decode('')
assert hashlib.sha256(source).hexdigest()=='67eb6dc025eecb0060d8c30b6bf92642d6228942c26d84a3aed9cffa4ceb210c'
tree=ast.parse(source);selected=ast.Module(body=[n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name in ('tau_sigmoid','step_rank')],type_ignores=[])
namespace={'torch':torch};exec(compile(selected,'official_smooth_rank_ap.py','exec'),namespace)
rows=[]
for t in [-0.02,0.,0.02,0.05,0.050001]:
 values=torch.tensor([[0.,t]],dtype=torch.float64)
 result=namespace['step_rank'](values,tau=.01,rho=100.,offset=1.44,delta=.05,target=torch.tensor([True,False]),general=True)
 rows.append(dict(negative_minus_positive=t,negative_rank_increment=float(result[0,1]),positive_rank_increment=float(result[0,0])))
zero=rows[1]['negative_rank_increment'];surrogate=1-1/(1+zero);hard=1-1/(1+1.)
assert zero==.5 and surrogate<hard
print(json.dumps(dict(status='COMPLETE_AUTHOR_CODE_FORWARD_MATH_CHECK',source_sha256=hashlib.sha256(source).hexdigest(),torch=torch.__version__,device='cpu',model_forwards=0,optimizer_updates=0,synthetic_only=True,rows=rows,exact_tie_one_positive_one_negative=dict(supap_loss=surrogate,heaviside_ge0_loss=hard),scope='actual author step_rank forward for published config; no project data, no gradient or retrieval claim')))
